/** RFC 9457 / RFC 7807 HTTP Problem Details payload (`Content-Type: application/problem+json`). */
export interface ProblemDetails {
  /**
   * For batch endpoints: zero-based index (in request order) of the item that failed.
   * Batches are atomic, so when this is present no item of the batch was applied.
   */
  batch_index?: number | null;
  /** Machine-readable error code slug (e.g. `"conflict"`, `"insufficient_funds"`, `"ship_not_berthed"`). */
  code: string;
  /** Human-readable explanation specific to this occurrence of the problem. */
  detail: string;
  insurable_value?: null | InsurableValueExceeded;
  provisions_shortfall?: null | ProvisionsShortfall;
  /** HTTP status code (e.g. `409`). */
  status: number;
  /** Short, human-readable summary of the problem type (e.g. `"Conflict"`). */
  title: string;
  /** URI reference identifying the problem type (e.g. `"urn:tradewinds:error:conflict"`). */
  type: string;
}

