/** Operational lifecycle state of a vessel. */
export type ShipStatus = "berthed" | "anchored_roadstead" | "sailing" | "sunk";

/**
 * A ship's stores: what its crew lives on. Stores take hold space (so they cut the cargo a ship
 * can load) and weigh the ship down, but they are not cargo: they cannot be sold, delivered or
 * carried as freight, and they are not insured cargo.
 */
export interface ShipStores {
  /**
   * Provisions the crew eats, in tons (fractional: the stores are kept exactly). A ton feeds
   * 100 crew-days at sea (eaten exactly, per leg), and in port half that, a ton per 200
   * crew-days (a hoy's ten hands a ton every twenty days). They take the whole tons they
   * start in the hold.
   */
  provisions_tons: number;
  /** Game days at sea these stores feed the ship's crew. */
  sea_days_remaining: number;
}

export interface ShipWarehouseTransferRequest {
  commodity_id?: null | CommodityId;
  items?: ShipCargoItem[];
  quantity?: null | PositiveTons;
  ship_id: string;
}

export interface ShipWarehouseTransferResult {
  cargo_manifest: CargoManifest;
  items_transferred: ShipCargoItem[];
  port_id: PortId;
  ship_id: string;
  turnaround_unlocks_at?: string | null;
}

/** Execution state of an asynchronous simulation job in the event queue. */
export type SimJobStatus = "pending" | "completed";

/** Where provisions moved into or out of a ship's stores come from or go to. */
export type StoresCounterpart = "cargo" | "warehouse";

export interface StoresTransferResult {
  cargo_manifest: CargoManifest;
  /** Cargo capacity left after the transfer (hold less cannons and stores). */
  effective_hold_capacity_tons: Tons;
  port_id: PortId;
  ship_id: string;
  stores: ShipStores;
  /** Set when the transfer crossed the quay (warehouse), which extends the stevedore turnaround. */
  turnaround_unlocks_at?: string | null;
}

/** Data of an SSE `auth_revoked` / `auth_expired` event, sent right before the stream ends. */
export interface StreamAuthEnded {
  code: string;
  detail: string;
}

export interface StreamEvent {
  company_id?: string | null;
  event_type: string;
  id: string;
  payload: unknown;
  port_id?: null | PortId;
  sea_zone_id?: null | SeaZoneId;
  timestamp: string;
}

/** Data of an SSE `gap` event: events may have been missed and the client should resync via REST. */
export interface StreamGap {
  detail: string;
  /** The resume id that could not be found. */
  last_event_id?: string | null;
  /**
   * `unknown_last_event_id`: the resume id is not in the event log (pruned past retention,
   * or never existed).
   */
  reason: string;
}

/** Execution time-in-force policy for a spot market order. */
export type TimeInForce = "ioc" | "gtc";

/** Signed physical weight or capacity denominated in metric tons (`1 ton = 1 hold capacity unit`). */
export type Tons = number;

/** Best price on one side of a book and the total remaining size resting at that price. */
export interface TopOfBookLevelResult {
  price_pence: PositivePence;
  quantity: Tons;
}

export interface TreasuryVaultsResult {
  company_id: string;
  vaults: VaultBalanceResult[];
}

export interface UnderwriteInsuranceBatchRequest {
  items: UnderwriteInsuranceRequest[];
}

export interface UnderwriteInsuranceRequest {
  policy_id: string;
  slice_bps: number;
}

export interface UnprovisionShipRequest {
  /** Where the provisions taken out of the stores go. */
  destination: StoresCounterpart;
  ship_id: string;
  tons: PositiveTons;
}

/**
 * Partial update for [`CompanySettings`]: only the fields present change. Unknown fields are
 * rejected, so a misspelt preference is an error rather than a silent no-op.
 */
export interface UpdateCompanySettingsRequest {
  auto_remit_for_bills?: boolean | null;
  auto_remit_min_reserve_pence?: null | Pence;
}

export interface VaultBalanceResult {
  account_id: string;
  account_type: AccountType;
  balance_pence: Pence;
  banking_region: BankingRegion;
}

/**
 * Estimated schedule of the rest of a voyage. An estimate, not a promise: it assumes no hazard
 * strikes and that each leg starts the moment the previous one ends. It already accounts for
 * load changes from stores eaten en route and for starvation (speed halved once the stores
 * run out); cargo lost to storm or pirates, a convoy losing its slowest member, a late sim worker
 * and a berth queue at the destination (arrival there can mean anchoring in the roadstead) are
 * not foreseen.
 */
export interface VoyageEstimate {
  /** Index into the route of the leg under way (or, before departure, the first leg). */
  current_leg_idx: number;
  /** Estimated arrival at the destination port (the last leg's estimate). */
  estimated_arrival_at: string;
  /** The remaining legs, from `current_leg_idx` on. */
  legs: LegEstimate[];
  /** Speed of the leg under way. */
  speed_centiknots: number;
}

export interface WarehouseInventory {
  commodity_id: CommodityId;
  company_id: string;
  created_at: string;
  /** Tons reserved by open inventory locks (resting asks, listed freight contracts). */
  locked_quantity: Tons;
  port_id: PortId;
  quantity: Tons;
  updated_at: string;
}

export interface WhoAmIResult {
  api_key_id: string;
  company_id?: string | null;
  expires_at?: string | null;
  player_id: string;
  scopes: ApiKeyScope[];
}

export interface WorldCatalogResult {
  commodities: CommodityDef[];
  ports: PortCatalogEntry[];
  sea_zones: SeaZoneDef[];
  ship_classes: ShipClassDef[];
}

export interface WorldClockResult {
  active_player_volume_24h: Pence;
  calendar: GameCalendarDate;
  global_health_bps: number;
  /**
   * The server operators have paused the world: game time stands still (`calendar` is frozen),
   * nothing at sea moves, and mutating requests answer `503 world_paused` until it resumes.
   */
  paused: boolean;
  real_utc: string;
  season_number: number;
  /**
   * When the operators have announced this season will end (seasons run a fixed 90 real days;
   * the operators end each one by hand on the announced date, never automatically). `null`
   * until announced. The final standings are archived then: `GET /v1/world/leaderboard`.
   */
  season_planned_end_at?: string | null;
  unlocked_phase: number;
}

/**
 * A world event as published: what happened where, in words. Never carries magnitudes or hidden
 * economy parameters (tonnages, rate factors, durations of structural shifts).
 */
export interface WorldEventResult {
  /** Piracy added in the sea zone (`pirate_outbreak`). */
  added_piracy_bps?: number | null;
  /**
   * The public charter the event spawned (`admiralty_mobilization`; a `demand_shortage` crisis
   * charter is local news, listed only on its quay or as gossip).
   */
  charter_id?: string | null;
  commodity_id?: null | CommodityId;
  description: string;
  event_type: WorldEventType;
  /** When the event (for a structural shift: the news of it) lapses. Not the end of a shift. */
  expires_at: string;
  id: string;
  /** Still in effect (`expires_at` in the future). */
  is_active: boolean;
  starts_at: string;
  /** A structural shift: a lasting change to a port's economy (how large or how long is not said). */
  structural: boolean;
  target_port_id?: null | PortId;
  target_sea_zone_id?: null | SeaZoneId;
  title: string;
}

/** Kind of a world event: one of the director's macro shocks, or a structural shift (§3.1a). */
export type WorldEventType = "supply_boom" | "demand_shortage" | "admiralty_mobilization" | "pirate_outbreak" | "production_collapse" | "production_boom" | "import_slump";

export type ZoneClass = "coastal" | "regional" | "oceanic";

